ddl:
CREATE TABLE Department (
    Department_Name VARCHAR(255) PRIMARY KEY,
    Floor VARCHAR(255)
);

CREATE TABLE Doctor (
    Doctor_ID INTEGER PRIMARY KEY,
    Gender VARCHAR(255),
    Name VARCHAR(255),
    Title VARCHAR(255)
);

CREATE TABLE Patient (
    Age INTEGER,
    Gender VARCHAR(255),
    Patient_Name VARCHAR(255) PRIMARY KEY
);

CREATE TABLE Medicine (
    Manufacturer VARCHAR(255),
    Medicine_Name VARCHAR(255) PRIMARY KEY,
    Price FLOAT
);

CREATE TABLE Prescription (
    Prescription_Information VARCHAR(255) PRIMARY KEY
);

CREATE TABLE Diagnosis_Management (
    Diagnosis_Information VARCHAR(255),
    Doctor_ID INTEGER NOT NULL,
    Patient_Name VARCHAR(255) NOT NULL,
    PRIMARY KEY (Doctor_ID, Patient_Name),
    FOREIGN KEY (Doctor_ID) REFERENCES Doctor(Doctor_ID),
    FOREIGN KEY (Patient_Name) REFERENCES Patient(Patient_Name)
);

CREATE TABLE Prescription_Management (
    Doctor_ID INTEGER NOT NULL,
    Patient_Name VARCHAR(255) NOT NULL,
    Prescription_Information VARCHAR(255),
    PRIMARY KEY (Doctor_ID, Patient_Name),
    FOREIGN KEY (Doctor_ID) REFERENCES Doctor(Doctor_ID),
    FOREIGN KEY (Patient_Name) REFERENCES Patient(Patient_Name)
);

CREATE TABLE Medicine_List_Management (
    Medicine_Name VARCHAR(255) NOT NULL,
    Prescription_Information VARCHAR(255) NOT NULL,
    Quantity INTEGER,
    PRIMARY KEY (Prescription_Information, Medicine_Name),
    FOREIGN KEY (Medicine_Name) REFERENCES Medicine(Medicine_Name),
    FOREIGN KEY (Prescription_Information) REFERENCES Prescription(Prescription_Information)
);
